def options(n,changes):
 for cid,(wording,why) in changes.items():
  assert cid!=QS[n-1]['answerId']
  next(c for c in SPECS[n]['choices'] if c['id']==cid).update(text=wording,explanation=why)

options(5,{'a':('已經完成','已在可以之後說能做甚麼，不能以已經完成代替應停止的行動。'),'c':('由自己決定','己與已不是同一字義，原句已指停止，不是把選擇留待本人決定。'),'d':('暫且如此','反問催促停止失義，並非讓目前做法暫時維持。')})
options(11,{'a':('暫且不吃魚','不吃仍可能保有，舍魚在取捨中是放棄，未說稍後可以取回。'),'b':('把魚送給別人','捨棄未必涉及受贈者，不能增加送人的情節。'),'c':('把魚存放起來','存放表示仍保有，與不能兼得而放棄魚的取捨不同。')})
options(15,{'a':('對死亡的憂慮','患是被辟的禍患，不是人內心憂慮這種反應。'),'b':('道義本身的缺陷','原文說可能遭遇的禍害，沒有把義本身評為缺陷。'),'c':('不願求生的態度','患指處境中的禍害，不是主觀態度，且孟子仍承認生命可欲。')})
options(21,{'a':('未曾遭遇禍患','勿喪的對象是本心，不是說賢者從未面對危險。'),'c':('不必再作取捨','保存本心恰須在取捨中守義，並非從此不用選擇。'),'d':('不能失去生命','所保存的是重義之心，不能換成保命，否則與舍生取義衝突。')})
options(28,{'a':('讓受食者參與施食','與之說給予受食者，沒有讓受食者加入施食工作的意思。'),'b':('贊成對方接受食物','給予是實際施予動作，贊成只是意見，不能替代與的句中義。'),'d':('和受食者一起進食','句子未說施者與受者同吃，不能把動詞與解成表示一起的介詞。')})
options(31,{'a':('用來救命的少量食物','少量救命飯食由簞食豆羹表達，萬鍾則是後面對照的厚祿。'),'b':('價值萬金的饋贈禮器','鍾在此涉及糧食容量和俸祿，並非價值萬金的鐘鼎器物。'),'c':('接濟窮人後所得的報酬','窮人感激是受祿者所求的回報之一，但萬鍾本身不是窮人付給他的報酬。')})
options(40,{'b':('同一人曾珍惜生命，後來承認享受也有價值','文章本就承認有所欲，失本心的問題是取利時放棄禮義，而非新增一種欲望。'),'c':('同一人曾收入不多，後來生活條件有所改善','改善生活不是失心的充分證據，還须指出不辨禮義的取利。'),'d':('同一人曾自行判斷，後來願意顧及家人需要','顧及家人未必失義，不能以此取代鄉今間守義準則的變化。')})
options(42,{'a':('重義超過求生→可以不再珍惜生命；厭惡不義超過死亡→應尋求所有禍患','原文仍欲生惡死，有所不避也不等於主動尋求一切禍患，兩項都過度擴張。'),'b':('重義超過求生→待安全後才守義；厭惡不義超過死亡→先保命再辨是非','守義不是等安全有保障才開始，兩項都把求生置於道義之前。'),'c':('求生超過重義→仍不苟生；厭惡死亡超過不義→仍不盡避患','原因將價值次序倒轉，便不能推出後面有所不為的結果。')})
options(46,{'a':('救命之食難以持續供應，厚祿能長久保命所以可以接受','原文沒有以長期供應解釋受祿，且仍不能用利益代替禮義判斷。'),'b':('救命之食出自陌生人，厚祿出自熟人所以可以接受','原文没有這種來源配對，所識窮人也不是厚祿提供者，陌生或相識不是取利判準。'),'c':('救命之食較少，厚祿較多，所以拒前受後只是同一價值尺度','份量多少雖有對照，核心却是救命尚守義、求享受反失義，不能抹去道德矛盾。')})
options(51,{'a':('只有少量食物能讓人保命，厚祿完全沒有生活用途','反問未否定厚祿所有用途，而是質疑它能否補償失義的代價。'),'b':('只要對厚祿心存感激，便已完成了禮義判斷','原文的感激是受祿者想從窮人得到的回報，不是受祿者自己的禮義審查。'),'d':('只要拒絕過受辱之食，往後接受任何厚祿都不必再辨義','本心仍須保存，昔日守義不會免去今日判斷；這正是鄉今對比要警醒的問題。')})
options(56,{'a':('賢者獨有的道德身分','人皆有之明確擴大範圍，不能仍解成只有賢者才有的身分。'),'b':('維持生存的基本欲望','欲生是人一般欲望，但之就近承是心，指高於求生的重義本心。'),'d':('面對誘惑仍永不失守的能力','人人有本心不等於人人永不失守，後句另提出能否保持的差別。')})
options(57,{'a':('這個人說過','此指前述失義做法，不是某位說話者，謂在此為命名判斷。'),'c':('這件事前往','之在此之謂中不是前往，整句是在把做法歸結為失本心。'),'d':('這樣便值得稱許','失其本心帶批評意味，謂是叫作，不是稱讚對方。')})
options(61,{'a':('取得生來已有的本心','得生談獲得生存，本心則是後文進一步提出的道德概念，不能調換。'),'c':('取得維生以外的享受','本段得生直接指活命，未轉入下段宮室之美等額外利益。'),'d':('只使別人免於死亡','原文討論自己所欲與採取的求生方法，沒有把對象限為別人。')})
options(62,{'b':('使用已取得的俸祿','前文得生限定求生方法，萬鍾尚未是此句所承對象。'),'c':('採用別人的道德評價','原句假設下問能活命的方法何不用，沒有以他人評價作直接賓語。'),'d':('享用救濟窮人的回報','感激回報屬後段的動機分析，不能移來充作何不用的對象。')})
options(63,{'a':('在此以後','後面是推論結論，不是交代其後發生甚麼的時間。'),'b':('即使如此','即使引讓步，原句則由前文證據推出結論，應作因此。'),'c':('依循此法','依循方法是由是的用法，是故在此則是因果總結，兩個詞組不可互換。')})
options(71,{'a':('總結人人曾經守義，因而推定每人以後都能守義','人皆有本心不等於每次都守住，更不能由曾經守義保證日後不失。'),'c':('把本心是否存在交由身分決定，再以乞人與賢者作高低比較','非獨、人皆明確否定本心按身分分配，乞人不是用來證明賢者天生更有本心。'),'d':('先總結本心人人皆有，再以此免除受厚祿者的失義責任','有本心更須保存，後文受祿失守仍受批評，不能把普遍擁有當成免責。')})
